INSERT INTO sentence_translations (id, sentence_id, lang, text, source) VALUES
  ('st-ex-nariimm-1', 'sent-ex-nariimm-1', 'en', 'The moment he sat down, he fell asleep.', 'authored'),
  ('st-ex-nariimm-2', 'sent-ex-nariimm-2', 'en', 'The moment he got home, he went to his room.', 'authored'),
  ('st-ex-nariimm-3', 'sent-ex-nariimm-3', 'en', 'The moment she heard, she cried.', 'authored'),
  ('st-ex-nariimm-4', 'sent-ex-nariimm-4', 'en', 'The moment he saw it, he laughed.', 'authored'),
  ('st-ex-sokoneru-1', 'sent-ex-sokoneru-1', 'en', 'I missed the train.', 'authored'),
  ('st-ex-sokoneru-2', 'sent-ex-sokoneru-2', 'en', 'I missed my chance to eat.', 'authored'),
  ('st-ex-sokoneru-3', 'sent-ex-sokoneru-3', 'en', 'I missed my chance to say thank you.', 'authored'),
  ('st-ex-sokoneru-4', 'sent-ex-sokoneru-4', 'en', 'I missed that film.', 'authored'),
  ('st-ex-kaneru-1', 'sent-ex-kaneru-1', 'en', 'I am not in a position to answer.', 'authored'),
  ('st-ex-kaneru-2', 'sent-ex-kaneru-2', 'en', 'I am afraid I cannot say.', 'authored'),
  ('st-ex-kaneru-3', 'sent-ex-kaneru-3', 'en', 'I am finding it hard to decide.', 'authored'),
  ('st-ex-kaneru-4', 'sent-ex-kaneru-4', 'en', 'I am afraid I cannot take that job on.', 'authored'),
  ('st-ex-madeda-1', 'sent-ex-madeda-1', 'en', 'If they turn me down, I will simply give up.', 'authored'),
  ('st-ex-madeda-2', 'sent-ex-madeda-2', 'en', 'If there is no train, I will simply walk.', 'authored'),
  ('st-ex-madeda-3', 'sent-ex-madeda-3', 'en', 'If it fails, I will simply do it again.', 'authored'),
  ('st-ex-madeda-4', 'sent-ex-madeda-4', 'en', 'If it cannot be helped, I will simply do it myself.', 'authored'),
  ('st-ex-mademonai-1', 'sent-ex-mademonai-1', 'en', 'It goes without saying.', 'authored'),
  ('st-ex-mademonai-2', 'sent-ex-mademonai-2', 'en', 'There is no need to explain.', 'authored'),
  ('st-ex-mademonai-3', 'sent-ex-mademonai-3', 'en', 'It is not something you need to ask about.', 'authored'),
  ('st-ex-mademonai-4', 'sent-ex-mademonai-4', 'en', 'There is no need to worry.', 'authored'),
  ('st-ex-nitaenai-1', 'sent-ex-nitaenai-1', 'en', 'I cannot thank you enough.', 'authored'),
  ('st-ex-nitaenai-2', 'sent-ex-nitaenai-2', 'en', 'My joy is more than I can bear.', 'authored'),
  ('st-ex-nitaenai-3', 'sent-ex-nitaenai-3', 'en', 'His talk is unbearable to listen to.', 'authored'),
  ('st-ex-nitaenai-4', 'sent-ex-nitaenai-4', 'en', 'It was a film I could not bear to watch.', 'authored'),
  ('st-ex-nokiwami-1', 'sent-ex-nokiwami-1', 'en', 'I was utterly exhausted.', 'authored'),
  ('st-ex-nokiwami-2', 'sent-ex-nokiwami-2', 'en', 'I could not be happier.', 'authored'),
  ('st-ex-nokiwami-3', 'sent-ex-nokiwami-3', 'en', 'It was utter confusion.', 'authored'),
  ('st-ex-nokiwami-4', 'sent-ex-nokiwami-4', 'en', 'The tension was at its height.', 'authored'),
  ('st-ex-nikatakunai-1', 'sent-ex-nikatakunai-1', 'en', 'It is not hard to imagine.', 'authored'),
  ('st-ex-nikatakunai-2', 'sent-ex-nikatakunai-2', 'en', 'His feelings are not hard to guess at.', 'authored'),
  ('st-ex-nikatakunai-3', 'sent-ex-nikatakunai-3', 'en', 'The result is not hard to predict.', 'authored'),
  ('st-ex-nikatakunai-4', 'sent-ex-nikatakunai-4', 'en', 'It is not hard to imagine him getting angry.', 'authored'),
  ('st-ex-kiwamarinai-1', 'sent-ex-kiwamarinai-1', 'en', 'It is extremely dangerous behaviour.', 'authored'),
  ('st-ex-kiwamarinai-2', 'sent-ex-kiwamarinai-2', 'en', 'It is the height of rudeness.', 'authored'),
  ('st-ex-kiwamarinai-3', 'sent-ex-kiwamarinai-3', 'en', 'It is an extremely inconvenient place.', 'authored'),
  ('st-ex-kiwamarinai-4', 'sent-ex-kiwamarinai-4', 'en', 'It was an unbelievably dull talk.', 'authored'),
  ('st-ex-noitari-1', 'sent-ex-noitari-1', 'en', 'I am deeply moved.', 'authored'),
  ('st-ex-noitari-2', 'sent-ex-noitari-2', 'en', 'I could not regret it more.', 'authored'),
  ('st-ex-noitari-3', 'sent-ex-noitari-3', 'en', 'I am extremely obliged to you.', 'authored'),
  ('st-ex-noitari-4', 'sent-ex-noitari-4', 'en', 'I could not be more delighted.', 'authored')
